WHERE m.daou_document_id = #{documentId}
   OR CAST(m.id AS VARCHAR) = #{documentId}
   OR CONCAT('MAP-', m.id) = #{documentId}
   OR CONCAT('ERP-', m.id) = #{documentId}
   OR CONCAT('REDIRECT-', m.id) = #{documentId}
   OR CONCAT('LOCAL-', m.id) = #{documentId}
LIMIT 1

mapper.update:
UPDATE erp_approval_mappings
SET status = #{status},
    daou_document_id = CASE
        WHEN #{newDaouDocumentId} IS NOT NULL AND #{newDaouDocumentId} != ''
            THEN #{newDaouDocumentId}
        ELSE daou_document_id
    END,
    updated_at = NOW()
WHERE daou_document_id = #{lookupId}
   OR CAST(id AS VARCHAR) = #{lookupId}
   OR CONCAT('MAP-', id) = #{lookupId}
   OR CONCAT('ERP-', id) = #{lookupId}
   OR CONCAT('REDIRECT-', id) = #{lookupId}
   OR CONCAT('LOCAL-', id) = #{lookupId}
